const topics=[
{id:'intro',title:'Meet ShAI',keywords:/\b(hello|hi|hey|who|shai|yourself|personality)\b/i,answer:"Hey, I’m ShAI—current Shai, digital edition. Think portfolio guide with a soft spot for clear workflows and a healthy suspicion of mystery metrics. I represent Shai’s work; I’m not Shai herself. Pick a project, ask how it works, or make me explain the security decisions.",source:'Owner-provided background and portfolio scope',href:'#home'},
{id:'background',title:'Shai’s professional focus',keywords:/\b(background|experience|career|healthcare|copilot|skills|qualified|hire)\b/i,answer:"Shai’s background spans AI adoption and enterprise AI solution design, healthcare IT, enterprise integrations, business analysis, stakeholder requirements, Copilot agents, Power Automate, REST APIs, and implementation. Her focus is connecting business needs with practical solutions. I don’t have verified employer names, dates, certifications, or a résumé here, so I won’t improvise those.",source:'Professional background supplied by Shai',href:'#contact'},
{id:'operations',title:'Operations Command Center',keywords:/\b(operations|dashboard|kpi|metrics|backlog|summary|anomal|data)\b/i,answer:"The Operations Command Center turns fictional service data into a clearer operational picture. Choose a team and period, inspect request volumes, and generate a briefing. The numbers are calculated first; explicit rules flag backlog growth and SLA below 90%. Right now, the briefing uses templates—not a live model. My favorite detail? You can inspect the evidence instead of trusting a confident paragraph.",source:'Project 1 implementation and calculation rules',href:'#operations'},
{id:'workflow',title:'Workflow Automation Studio',keywords:/\b(workflow|automation|approval|ticket|request|routing|agent)\b/i,answer:"The Workflow Studio validates a fictional request, classifies it with keywords, proposes a route, and drafts a response. Then a human approves or rejects that exact draft. Edit the input and approval resets. Ambiguous requests go to manual triage. Nothing is emailed or routed externally—this is a supervised simulation, with its steps visible in the activity log.",source:'Project 2 implementation and approval controls',href:'#workflow'},
{id:'security',title:'Security and boundaries',keywords:/security/i,answer:''},
{id:'architecture',title:'How the portfolio works',keywords:/\b(architecture|stack|code|built|build|works|technology|api|model|ai)\b/i,answer:"The public portfolio is HTML, CSS, and JavaScript, hosted on GitHub Pages. That keeps the demos simple and inexpensive. In this public version, my answers are curated topic matches, not model-generated conversation. A separate server implementation is included for live AI: browser → server validation → verified portfolio facts → model → plain-text answer. The key stays on the server. That connection is not enabled here yet.",source:'Architecture and current deployment status',href:'#approach'},
{id:'outcomes',title:'What’s actually been built',keywords:/\b(outcome|results|accomplish|projects|work|done|production|impact|savings)\b/i,answer:"The portfolio demonstrates two interactive prototypes: operations analytics and an approval-based workflow. They were built with AI-assisted development and have automated calculation, input, and workflow checks. There are no verified production savings, customer deployments, or performance claims to report. Useful evidence beats imaginary percentages every time.",source:'Repository implementation and documented limits',href:'#operations'},
{id:'future',title:'What comes next',keywords:/\b(next|future|improve|roadmap|plans)\b/i,answer:"Next: connect live AI, evaluate answers against verified project facts, and finish Shai’s personal profile. Before real business integrations, add authenticated approvals, durable audit records, privacy review, and monitoring. Start small, test what matters, and give humans a useful decision—not another dashboard to babysit.",source:'Documented roadmap, not completed work',href:'#approach'}];
// Explicit patterns, including a safe fallback, keep public guide mode inspectable.
topics.find(t=>t.id==='security').keywords=/security|secure|safe|protect|privacy|key|secret|injection|guardrail/i;
