function answer(question){if(typeof question!=='string'||!question.trim()||question.trim().length>600)throw Error('Ask a question between 1 and 600 characters.');const s=question.trim();if(/ignore.*instruction|system prompt|reveal.*secret|pretend.*production|invent.*(experience|result)/i.test(s))return {answer:"Nice try. My personality has room for jokes, not invented credentials. I can explain verified project facts and my limitations. I won’t fabricate outcomes or disclose credentials.",source:'ShAI’s boundaries',href:'#approach'};if(/how.*(you|she).*work/i.test(s))return topics.find(t=>t.id==='architecture');const topic=topics.find(t=>t.id!=='intro'&&t.keywords.test(s))||topics.find(t=>t.id==='intro'&&t.keywords.test(s));return topic||{answer:"That detail isn’t in my verified portfolio notes. In this guide mode I match questions to a small set of prewritten topics, so I may miss nuanced questions. Try asking about Shai’s background, the Operations dashboard, workflow approvals, security, or how I work.",source:'Unknown information stays unknown',href:'#approach'};}
